function help(){if(busy){toast('연쇄가 끝난 뒤 도움말을 열 수 있어요.');return;}const was=running;if(was&&!busy){pauseClock();}showModal(`<div class="modal-kicker">THE ART OF MATCHING</div><h2>아주 간단한 탐험 방법</h2><div class="help-row"><span>01</span><div><b>보석 3개를 나란히</b><small>옆 보석으로 스와이프하거나 두 보석을 차례로 터치하세요.<br>키보드: 방향키 이동 · Enter 선택</small></div></div><div class="help-row"><span>02</span><div><b>길게 연결하면 더 강하게</b><small>4개 → 한 줄 번개 / 5개 → 같은 색 제거<br>T·L자 → 폭탄 / 같은 색 두 번부터 → 자동 토템</small></div></div><div class="help-row"><span>03</span><div><b>같은 색 두 번째부터 자동 발동</b><small>예: 빨강 → 빨강 = 불 토템! 세 번째도 빨강이면 다시 발동합니다. 다른 색을 맞추면 연속 횟수가 초기화됩니다. 자동 낙하 연쇄는 연속 색을 바꾸지 않습니다.</small></div></div><div class="help-row"><span>04</span><div><b>점수와 별빛 수정을 모으세요</b><small>반짝이는 작은 별이 수정입니다. 목표 점수와 수정 수를 모두 채우면 다음 스테이지! 클리어 마법별로 토템을 Lv.5까지 강화하세요. 전체 100개 스테이지.</small></div></div><div class="settings-row"><span>화면 효과 줄이기</span><button id="motionToggle">${reduced?'켜짐':'꺼짐'}</button></div><button id="helpClose" class="primary-button">알겠어요 · 탐험으로 →</button>`);$('#helpClose').onclick=resume;$('#motionToggle').onclick=e=>{reduced=!reduced;document.body.classList.toggle('reduced-motion',reduced);e.target.textContent=reduced?'켜짐':'꺼짐';persist();};}
async function trySwap(a,b){if(busy||!ensureStarted()||!adjacent(a,b))return;busy=true;frame.setAttribute('aria-busy','true');selected=-1;hint=[];lastAction=performance.now();[board[a],board[b]]=[board[b],board[a]];syncPositions();tone(280,.06);await wait(reduced?25:155);const groups=findMatches(board);if(!groups.length){[board[a],board[b]]=[board[b],board[a]];syncPositions();await wait(reduced?20:150);busy=false;tone(150,.08,'triangle');if(finishAfterBusy)finish(false);return;}combo=1;const primary=groups.find(g=>g.cells.includes(b))??groups.find(g=>g.cells.includes(a))??groups[0];totemChain=advanceTotem(totemChain,primary.color);updateTotemUI();await resolve(groups,[b,a]);if(totemChain.trigger&&totemUnlocked(primary.color)&&!ended){await castTotem(primary.color,b);}busy=false;checkEnd();update();}
async function resolve(groups,preferred=[]){for(let depth=0;groups.length&&depth<24;depth++){const creation=specialCreations(groups,preferred);const cells=[...new Set(groups.flatMap(g=>g.cells))];await clearCells(cells,creation,combo);await settle(false);groups=findMatches(board);preferred=[];combo++;}if(findMatches(board).length){board=makeBoard();syncPositions(true);toast('사원의 기운이 보석을 새롭게 배치했어요.');}}
