async function clearCells(indices,creations=new Map(),chain=1){const result=affected(board,indices);for(const {index,type,color}of result.effects){const r=Math.floor(index/8),c=index%8;if(type==='row'||type==='cross')beam(r*8,r*8+7,PALETTE[color][1]);if(type==='col'||type==='cross')beam(c,56+c,PALETTE[color][1]);if(type==='bomb'||type==='nova'){ring(c+.5,r+.5,PALETTE[color][1],type==='nova'?3:1.7);shake();}}let gained=0,collected=0;for(const i of result.cells){const g=board[i];if(!g)continue;gained+=50*Math.min(chain,8)*(performance.now()<frenzyUntil?3:1);if(g.crystal)collected++;burst(i,g.color,chain>2?14:9);if(!creations.has(i)){ghosts.push({g:{...g},life:1});board[i]=null;}}for(const [i,special]of creations){if(board[i]){board[i].special=special;board[i].crystal=false;ring(i%8+.5,Math.floor(i/8)+.5,PALETTE[board[i].color][1],1.1);}}score+=gained;crystals+=collected;if(collected)tone(1100,.22,'sine',.06);frenzy=Math.min(100,frenzy+result.cells.length*2.2);if(frenzy>=100&&performance.now()>=frenzyUntil){frenzy=0;frenzyUntil=performance.now()+10000;announce('SOLAR AWAKENING','태양의 각성 · 모든 점수 3배',1500);chord(7);flash();shake();}if(gained){const middle=result.cells[Math.floor(result.cells.length/2)]??27;floats.push({x:middle%8+.5,y:Math.floor(middle/8)+.5,text:`+${gained.toLocaleString()}`,life:1.2,color:chain>1?'#ffe2a1':'#d2f3dd'});}if(chain>1){$('#boardHint').textContent=`${chain}연쇄 · 보석이 깨어납니다!`;if(chain>=3)announce(`${chain} COMBO`,chain>=5?'경이로운 연쇄!':'빛나는 연결',650);}tone(360*Math.pow(1.12,Math.min(chain,10)),.12,'triangle',.055);vibrate(chain>=3?35:12);if(chain>=3)shake();best=Math.max(best,score);update();await wait(reduced?25:165);}
function checkEnd(){if(ended)return;const obj=objectives(level);if(score>=obj.target&&crystals>=obj.crystals){finish(true);return;}if(finishAfterBusy||time<=0){finish(false);return;}if(!findMove(board)){board=makeBoard();syncPositions(true);announce('새로운 흐름','가능한 매치가 없어 자동으로 섞었어요');}persist();}
function finish(win){if(ended)return;ended=true;running=false;paused=false;activePower=null;frenzyUntil=0;best=Math.max(best,score);const earnedStars=win?Math.min(3,1+(time>25?1:0)+(score>objectives(level).target*1.4?1:0)):0;const newStars=win?stageReward(stageStars[level-1],earnedStars):0;if(win){stageStars[level-1]=Math.max(stageStars[level-1],earnedStars);magicStars+=newStars;unlocked=Math.max(unlocked,Math.min(STAGE_COUNT,level+1));chord(12);flash();for(let i=0;i<8;i++)burst(Math.floor(Math.random()*64),3,25);}
persist();update();const stars=earnedStars;showModal(`<div class="modal-kicker">${win?'TEMPLE AWAKENED':'A NEW DAWN AWAITS'}</div><h2>${win?(level===STAGE_COUNT?'태양의 유산을 찾았습니다':'사원의 문이 열렸습니다'):'다시 깨어날 시간'}</h2><div class="result-stars">${win?'★'.repeat(stars)+'☆'.repeat(3-stars):'✦'}</div><div class="result-stats"><div><b>${score.toLocaleString()}</b><span>획득 점수</span></div><div><b>${crystals}</b><span>별빛 수정</span></div></div><p class="stars-caption">${win?(level===STAGE_COUNT?'100개의 스테이지를 모두 탐험했습니다. 멋진 여정이었어요.':`마법별 +${newStars}개 · 보유 ${magicStars}개<br>토템을 강화하고 다음 스테이지에 도전하세요.`):`목표: ${objectives(level).target.toLocaleString()}점 + 수정 ${objectives(level).crystals}개<br>시간 없는 휴식 모드에서도 연습할 수 있어요.`}</p><button id="nextBtn" class="primary-button">${win&&level<STAGE_COUNT?'다음 사원으로 →':'다시 도전하기 →'}</button>${win?'<button id="resultUpgrade" class="text-button">토템 강화 <span>↗</span></button>':''}${!win?'<button id="zenResult" class="text-button">시간 없는 휴식으로 <span>∞</span></button>':''}`);$('#nextBtn').onclick=()=>{if(win&&level<STAGE_COUNT)level++;reset();start();};if($('#resultUpgrade'))$('#resultUpgrade').onclick=()=>openUpgrades();if($('#zenResult'))$('#zenResult').onclick=()=>{mode='zen';reset();start();};}
function select(i){if(busy||paused||ended||$('#modal').open)return;if(selected===i){selected=-1;return;}if(selected>=0&&adjacent(selected,i)){trySwap(selected,i);return;}selected=i;lastAction=performance.now();tone(400+board[i].color*40,.05);}
let pointer=null;
wrap.addEventListener('pointerdown',e=>{if(e.button!==0)return;const rect=wrap.getBoundingClientRect();const x=(e.clientX-rect.left)/rect.width*8,y=(e.clientY-rect.top)/rect.height*8;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,i:Math.floor(y)*8+Math.floor(x),width:rect.width};wrap.setPointerCapture(e.pointerId);});
wrap.addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const p=pointer;pointer=null;const dx=e.clientX-p.x,dy=e.clientY-p.y;if(p.i<0||p.i>=64)return;if(Math.hypot(dx,dy)>p.width/8*.3){let b=p.i+(Math.abs(dx)>Math.abs(dy)?(dx>0?1:-1):(dy>0?8:-8));if(b>=0&&b<64&&adjacent(p.i,b))trySwap(p.i,b);}else select(p.i);});wrap.addEventListener('pointercancel',()=>pointer=null);
$('#boardInput').addEventListener('keydown',e=>{const i=+e.target.dataset.cell;if(!Number.isFinite(i))return;const delta={ArrowRight:1,ArrowLeft:-1,ArrowUp:-8,ArrowDown:8}[e.key];if(delta){e.preventDefault();const j=i+delta;if(j>=0&&j<64&&adjacent(i,j)){e.target.tabIndex=-1;const b=$('#boardInput').children[j];b.tabIndex=0;b.focus();}}if(e.key==='Enter'||e.key===' '){e.preventDefault();select(i);}});
