$('#startBtn').onclick=start;$('#pauseBtn').onclick=()=>paused?resume():pause();$('#helpBtn').onclick=help;$('#soundBtn').onclick=()=>{sound=!sound;tone(660,.15);persist();update();};$('#closeModal').onclick=resume;$('#modal').addEventListener('cancel',e=>{e.preventDefault();resume();});
$$('[data-mode]').forEach(b=>b.onclick=()=>{if(started&&!ended)return;mode=b.dataset.mode;reset();toast(mode==='zen'?'시간 제한 없이, 편안하게 즐기세요.':'90초 동안 고대 사원을 깨우세요.');});
$('#hintBtn').onclick=()=>{if(busy||paused||ended)return;hint=findMove(board)||[];hintUntil=performance.now()+3500;if(hint.length)toast('빛나는 두 보석을 서로 바꿔보세요.');};
$('#shuffleBtn').onclick=()=>{if(busy||paused||ended)return;if(!shuffleLeft){toast('섞기를 모두 사용했어요. 다음 스테이지에 충전됩니다.');return;}shuffleLeft--;board=makeBoard();selected=-1;hint=[];syncPositions(true);ring(4,4,'#bde5b9',4);tone(450,.18);toast('보석에 새로운 기운이 깃들었어요.');update();};
$('#mapBtn').onclick=()=>openMap();
$('#mobileMap').onclick=()=>$('#mapBtn').click();
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){pauseClock();}else if(!document.hidden&&paused&&!$('#modal').open){pause();}update();});
// Canvas rendering stays independent of puzzle logic so cascades never block input accounting.
function resize(){const dpr=Math.min(devicePixelRatio||1,2);boardSize=wrap.clientWidth;cell=boardSize/8;canvas.width=Math.round(boardSize*dpr);canvas.height=Math.round(boardSize*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
new ResizeObserver(resize).observe(wrap);resize();
function polygon(points,scale=1){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x*scale,y*scale):ctx.moveTo(x*scale,y*scale));ctx.closePath();}
function drawGem(g,x,y,scale=1,alpha=1,now=0){const p=PALETTE[g.color],points=shapes[g.color];ctx.save();ctx.translate(x,y);ctx.scale(cell*scale,cell*scale);ctx.globalAlpha=alpha;ctx.shadowColor=p[1]+'70';ctx.shadowBlur=cell*.14;ctx.shadowOffsetY=cell*.055;polygon(points);const base=ctx.createLinearGradient(-.3,-.4,.2,.4);base.addColorStop(0,p[0]);base.addColorStop(.23,p[1]);base.addColorStop(.75,p[2]);base.addColorStop(1,p[3]);ctx.fillStyle=base;ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;
const inner=points.map(([a,b])=>[a*.62,b*.62]);for(let j=0;j<points.length;j++){const k=(j+1)%points.length;ctx.beginPath();ctx.moveTo(...points[j]);ctx.lineTo(...points[k]);ctx.lineTo(...inner[k]);ctx.lineTo(...inner[j]);ctx.closePath();ctx.fillStyle=j<2?'#ffffff58':j<4?'#0000002e':'#ffffff18';ctx.fill();ctx.beginPath();ctx.moveTo(...inner[j]);ctx.lineTo(...inner[k]);ctx.lineTo(-.055,-.075);ctx.closePath();ctx.fillStyle=j%3===0?'#ffffff20':j%3===1?'#00000018':'#ffffff07';ctx.fill();}
polygon(points);ctx.strokeStyle=p[0]+'a8';ctx.lineWidth=.014;ctx.stroke();polygon(inner);ctx.strokeStyle='#ffffff25';ctx.lineWidth=.01;ctx.stroke();ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]+.015);ctx.lineTo(points[1][0],points[1][1]+.015);ctx.strokeStyle='#ffffffcc';ctx.lineWidth=.018;ctx.stroke();
ctx.globalAlpha=alpha*.48;ctx.strokeStyle='#eafff5';ctx.lineWidth=.016;ctx.beginPath();if(g.color===0){ctx.moveTo(0,-.13);ctx.lineTo(.11,0);ctx.lineTo(0,.13);ctx.lineTo(-.11,0);ctx.closePath();ctx.moveTo(0,-.07);ctx.lineTo(0,.07);}if(g.color===1){ctx.moveTo(-.08,.08);ctx.lineTo(0,-.12);ctx.lineTo(.08,.08);ctx.lineTo(-.08,.08);}if(g.color===2){ctx.arc(0,0,.1,0,Math.PI*2);ctx.moveTo(0,-.16);ctx.lineTo(0,.16);ctx.moveTo(-.16,0);ctx.lineTo(.16,0);}if(g.color===3){ctx.arc(0,0,.08,0,Math.PI*2);for(let a=0;a<8;a++){ctx.moveTo(Math.cos(a*Math.PI/4)*.12,Math.sin(a*Math.PI/4)*.12);ctx.lineTo(Math.cos(a*Math.PI/4)*.17,Math.sin(a*Math.PI/4)*.17);}}if(g.color===4){ctx.moveTo(-.07,-.12);ctx.quadraticCurveTo(.13,0,-.07,.12);ctx.quadraticCurveTo(.03,0,-.07,-.12);}if(g.color===5){ctx.moveTo(-.13,.06);ctx.lineTo(0,-.14);ctx.lineTo(.13,.06);ctx.moveTo(-.09,.01);ctx.lineTo(0,.15);ctx.lineTo(.09,.01);}ctx.stroke();ctx.globalAlpha=alpha;
const glint=.3+.45*Math.sin(now/1000+g.id*2);ctx.fillStyle=`rgba(255,255,255,${glint})`;ctx.beginPath();ctx.ellipse(-.15,-.23,.065,.018,-.7,0,Math.PI*2);ctx.fill();
if(g.crystal){ctx.save();ctx.translate(.22,.21);ctx.shadowColor='#e9ffd8';ctx.shadowBlur=7;ctx.fillStyle='#f4ffdf';ctx.beginPath();for(let n=0;n<8;n++){const a=n*Math.PI/4-Math.PI/2,rad=n%2?.035:.10;ctx.lineTo(Math.cos(a)*rad,Math.sin(a)*rad);}ctx.closePath();ctx.fill();ctx.restore();}
if(g.special){ctx.shadowBlur=10;ctx.shadowColor='#ffecb0';ctx.strokeStyle='#fff9d2';ctx.fillStyle='#fff9d2';ctx.lineWidth=.035;ctx.beginPath();if(g.special==='row'||g.special==='cross'){ctx.moveTo(-.34,0);ctx.lineTo(.34,0);ctx.moveTo(-.25,-.05);ctx.lineTo(-.34,0);ctx.lineTo(-.25,.05);ctx.moveTo(.25,-.05);ctx.lineTo(.34,0);ctx.lineTo(.25,.05);}if(g.special==='col'||g.special==='cross'){ctx.moveTo(0,-.34);ctx.lineTo(0,.34);}if(g.special==='bomb'){ctx.arc(0,0,.18,0,Math.PI*2);ctx.moveTo(-.12,-.12);ctx.lineTo(.12,.12);ctx.moveTo(.12,-.12);ctx.lineTo(-.12,.12);}if(g.special==='nova'){for(let a=0;a<10;a++){const r=a%2?.11:.25;ctx.lineTo(Math.cos(a*Math.PI/5-Math.PI/2)*r,Math.sin(a*Math.PI/5-Math.PI/2)*r);}ctx.closePath();}ctx.stroke();ctx.shadowBlur=0;}ctx.restore();}
function burst(i,color,count=10){if(reduced)count=3;const x=i%8+.5,y=Math.floor(i/8)+.5;for(let k=0;k<count&&particles.length<550;k++){const a=Math.random()*Math.PI*2,v=.6+Math.random()*2.8;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-1,life:.45+Math.random()*.5,max:1,size:.025+Math.random()*.05,color:PALETTE[color][k%2],rot:Math.random()*6});}}
function ring(x,y,color,max=2){rings.push({x,y,color,max,r:.1,life:1});}
function beam(a,b,color){const points=[],x1=a%8+.5,y1=Math.floor(a/8)+.5,x2=b%8+.5,y2=Math.floor(b/8)+.5;for(let n=0;n<=12;n++){const t=n/12;points.push([x1+(x2-x1)*t+(n&&n<12?(Math.random()-.5)*.28:0),y1+(y2-y1)*t+(n&&n<12?(Math.random()-.5)*.28:0)]);}beams.push({points,color,life:.65});}
function draw(now,dt){ctx.clearRect(0,0,boardSize,boardSize);const bg=ctx.createLinearGradient(0,0,boardSize,boardSize);bg.addColorStop(0,'#0c292e');bg.addColorStop(1,'#05191f');ctx.fillStyle=bg;ctx.fillRect(0,0,boardSize,boardSize);for(let i=0;i<64;i++){const x=i%8*cell,y=Math.floor(i/8)*cell;ctx.fillStyle=(Math.floor(i/8)+i%8)%2?'#183c3e44':'#03161c60';ctx.fillRect(x+1,y+1,cell-2,cell-2);ctx.strokeStyle='#a2bfa512';ctx.lineWidth=.5;ctx.strokeRect(x+.5,y+.5,cell-1,cell-1);}
const hintOn=hintUntil>now||(now-lastAction>8000&&started&&!busy&&!activePower);if(hintOn&&!hint.length)hint=findMove(board)||[];for(const i of (selected>=0?[selected]:hintOn?hint:[])){const x=i%8*cell,y=Math.floor(i/8)*cell;ctx.save();ctx.strokeStyle=selected===i?'#ffdf91':`rgba(208,243,193,${.45+.35*Math.sin(now/200)})`;ctx.lineWidth=2;ctx.shadowColor='#f1dc92';ctx.shadowBlur=12;ctx.beginPath();ctx.roundRect(x+3,y+3,cell-6,cell-6,8);ctx.stroke();ctx.restore();}
board.forEach((g,i)=>{if(!g)return;const speed=Math.min(1,dt*19);g.x+=(g.tx-g.x)*speed;g.y+=(g.ty-g.y)*speed;const hovered=selected===i;drawGem(g,(g.x+.5)*cell,(g.y+.5)*cell,hovered?1.07:1,1,now);});
for(const g of ghosts){g.life-=dt*5;drawGem(g.g,(g.g.x+.5)*cell,(g.g.y+.5)*cell,1+(1-g.life)*.45,Math.max(0,g.life),now);}ghosts=ghosts.filter(g=>g.life>0);
ctx.save();ctx.globalCompositeOperation='lighter';for(const ring of rings){ring.r+=(ring.max-ring.r)*dt*6;ring.life-=dt*1.65;ctx.strokeStyle=ring.color;ctx.globalAlpha=Math.max(0,ring.life)*.7;ctx.lineWidth=2*ring.life;ctx.shadowBlur=15;ctx.shadowColor=ring.color;ctx.beginPath();ctx.arc(ring.x*cell,ring.y*cell,ring.r*cell,0,Math.PI*2);ctx.stroke();}rings=rings.filter(r=>r.life>0);ctx.shadowBlur=0;
for(const b of beams){b.life-=dt*2.1;ctx.globalAlpha=Math.max(0,b.life);ctx.strokeStyle=b.color;ctx.lineWidth=5;ctx.shadowColor=b.color;ctx.shadowBlur=18;ctx.beginPath();b.points.forEach(([x,y],i)=>i?ctx.lineTo(x*cell,y*cell):ctx.moveTo(x*cell,y*cell));ctx.stroke();ctx.strokeStyle='#ffffff';ctx.lineWidth=1.4;ctx.stroke();}beams=beams.filter(b=>b.life>0);ctx.shadowBlur=0;
for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=3.4*dt;p.rot+=dt*5;ctx.save();ctx.translate(p.x*cell,p.y*cell);ctx.rotate(p.rot);ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(-p.size*cell/2,-p.size*cell/2,p.size*cell,p.size*cell);ctx.restore();}particles=particles.filter(p=>p.life>0);ctx.restore();for(const f of floats){f.life-=dt;f.y-=dt*.65;ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,f.life*2));ctx.textAlign='center';ctx.font=`600 ${cell*.34}px Georgia`;ctx.fillStyle=f.color;ctx.shadowColor='#02161b';ctx.shadowBlur=5;ctx.fillText(f.text,f.x*cell,f.y*cell);ctx.restore();}floats=floats.filter(f=>f.life>0);
if(paused){ctx.fillStyle='#031c2477';ctx.fillRect(0,0,boardSize,boardSize);}}
const atm=$('#atmosphere'),ac=atm.getContext('2d');let aw=0,ah=0,ambient=Array.from({length:32},()=>({x:Math.random(),y:Math.random(),s:.4+Math.random()*1.6,speed:.01+Math.random()*.02,phase:Math.random()*6}));function atmosphere(now,dt){if(aw!==innerWidth||ah!==innerHeight){aw=innerWidth;ah=innerHeight;atm.width=aw;atm.height=ah;}ac.clearRect(0,0,aw,ah);if(reduced)return;for(const p of ambient){p.y-=dt*p.speed;if(p.y<0){p.y=1;p.x=Math.random();}const a=.15+.4*(.5+.5*Math.sin(now/1400+p.phase));ac.fillStyle=`rgba(234,198,112,${a})`;ac.shadowColor='#e9bc6a';ac.shadowBlur=9;ac.beginPath();ac.arc(p.x*aw+Math.sin(now/3000+p.phase)*15,p.y*ah,p.s,0,Math.PI*2);ac.fill();}}
let uiTick=0;function tick(now){const elapsed=Math.min((now-lastTick)/1000,.15);lastTick=now;const dt=elapsed||.016;if(running&&!paused&&!ended){if(frozen>0){frozen=Math.max(0,frozen-elapsed);if(!frozen)frame.classList.remove('frozen-board');}else if(mode!=='zen'){time=Math.max(0,time-elapsed);}if(now>frenzyUntil&&frenzy>0&&now-lastAction>2500)frenzy=Math.max(0,frenzy-elapsed*1.8);if(time<=0&&mode!=='zen'){if(busy)finishAfterBusy=true;else finish(false);}}
if(!document.hidden){draw(now,dt);atmosphere(now,dt);}uiTick+=dt;if(uiTick>.15){update();uiTick=0;}requestAnimationFrame(tick);}
renderTotems();syncPositions(true);time=objectives(level).time;update();requestAnimationFrame(tick);

function updateTotemUI(){const col=totemChain.color,count=totemChain.count;$$('[data-totem]').forEach(el=>{const i=+el.dataset.totem,available=totemUnlocked(i),armed=available&&col===i&&count>=1,casting=totemFlash===i&&performance.now()<totemFlashUntil;el.classList.toggle('locked',!available);el.classList.toggle('armed',armed);el.classList.toggle('casting',casting);el.querySelector('.totem-level').textContent='Lv.'+totemLevels[i];el.querySelector('.power-meter i').style.width=available?(col===i?(count>=2?'100%':'50%'):'0%'):'0%';el.querySelector('.power-state').textContent=!available?'S'+TOTEMS[i].unlock:casting?'발동!':armed?(count>=2?count+'연속':'1/2'):'0/2';});$('#powerInstruction').textContent=col>=0?colorNames[col]+' '+count+'연속 · '+(totemUnlocked(col)?'같은 색을 한 번 더 맞추세요':TOTEMS[col].unlock+'단계에서 토템 해금'):'같은 색 2번째 매치부터 자동 발동';$('#boardHint').textContent=col>=0?colorNames[col]+' '+count+'연속 · 같은 색이면 토템 발동':'같은 색을 두 번 연속 맞춰보세요';$('#starWallet').textContent='★ '+magicStars;}
async function castTotem(color,index){const l=totemLevels[color],t=TOTEMS[color];totemFlash=color;totemFlashUntil=performance.now()+1500;totalTotemCasts++;announce(t.name+' · Lv.'+l, t.color+' '+totemChain.count+'연속 · 자동 발동',1100);chord(color);shake();vibrate([20,25,45]);let cells=[];const r=Math.floor(index/8),c=index%8;
if(color===1){for(let k=0;k<l;k++){const center=k?Math.floor(Math.random()*64):index;const rr=Math.floor(center/8),cc=center%8,rad=l>=4?2:1;ring(cc+.5,rr+.5,t.accent,rad+1);beam(k%2?7:0,center,t.accent);for(let y=Math.max(0,rr-rad);y<=Math.min(7,rr+rad);y++)for(let x=Math.max(0,cc-rad);x<=Math.min(7,cc+rad);x++)cells.push(y*8+x);}flash('#ff9a72');}
if(color===2){for(let k=0;k<l;k++){const line=(k+r)%8;if(k%2){for(let y=0;y<8;y++)cells.push(y*8+((c+k)%8));beam((c+k)%8,56+(c+k)%8,t.accent);}else{for(let x=0;x<8;x++)cells.push(line*8+x);beam(line*8,line*8+7,t.accent);}}flash('#a5dfff');}
if(color===0){const gems=board.flatMap((g,i)=>g.crystal?[i]:[]).sort(()=>Math.random()-.5).slice(0,l+1);cells.push(...gems);for(const i of gems)beam(i,index,t.accent);const candidates=board.flatMap((g,i)=>!g.crystal&&!gems.includes(i)?[i]:[]).sort(()=>Math.random()-.5).slice(0,l+1);candidates.forEach(i=>{board[i].crystal=true;ring(i%8+.5,Math.floor(i/8)+.5,t.accent,.7);});ring(c+.5,r+.5,t.accent,2.7);}
if(color===3){const bonus=300*l*(performance.now()<frenzyUntil?3:1);score+=bonus;frenzy=Math.min(100,frenzy+15+l*5);if(l>=4||frenzy>=100){frenzy=0;frenzyUntil=performance.now()+10000+l*1000;announce('SOLAR AWAKENING','황금 토템 · 점수 3배',1400);}floats.push({x:4,y:3,text:'+'+bonus,life:1.4,color:'#ffda82'});ring(c+.5,r+.5,t.accent,4);flash();}
if(color===4){const candidates=board.flatMap((g,i)=>!g.special?[i]:[]).sort(()=>Math.random()-.5).slice(0,l);candidates.forEach((i,k)=>{board[i].special=l>=4&&k===0?'nova':k%2?'row':'bomb';beam(index,i,t.accent);ring(i%8+.5,Math.floor(i/8)+.5,t.accent,1);});}
if(color===5){const added=3+l*2;if(mode!=='zen')time+=added;if(l>=3){frozen=Math.max(frozen,l);frame.classList.add('frozen-board');}floats.push({x:4,y:3,text:mode==='zen'?'시간의 축복':'+'+added+'초',life:1.4,color:'#ffd7a1'});ring(4,4,t.accent,5);flash('#ffcf9c');}
update();await wait(reduced?20:260);if(cells.length){await clearCells([...new Set(cells)],new Map(),1);await settle();}else{accessBoard();await wait(reduced?20:140);}best=Math.max(best,score);update();}
function openUpgrades(focus=-1){if(busy){toast('연쇄가 끝난 뒤 토템을 강화할 수 있어요.');return;}if(running)pauseClock();showModal('<div class="modal-kicker">THE TOTEM SANCTUARY</div><h2>고대 토템 강화</h2><div class="wallet-title">★ '+magicStars+' <small>보유 마법별 · 스테이지 클리어로 획득</small></div><div class="upgrade-list">'+TOTEMS.map((t,i)=>{const l=totemLevels[i],cost=upgradeCost(l),available=totemUnlocked(i);return '<div class="upgrade-row '+(focus===i?'focused':'')+'" style="--accent:'+t.accent+'"><span class="upgrade-symbol totem-art" style="background-position:'+(i%3)*50+'% '+Math.floor(i/3)*100+'%"></span><div><b>'+t.name+' <span>Lv.'+l+'</span></b><small>'+(!available?'스테이지 '+t.unlock+' 도달 시 해금':totemEffectText(i))+'</small><span class="level-pips">'+Array.from({length:5},(_,n)=>'<i class="'+(n<l?'filled':'')+'"></i>').join('')+'</span></div><button data-upgrade="'+i+'" '+(!available||!cost||magicStars<cost?'disabled':'')+'>'+(!available?'잠김':!cost?'MAX':'★ '+cost+' 강화')+'</button></div>';}).join('')+'</div><p class="upgrade-help">같은 색을 직접 2번 연속 맞추면 자동 발동합니다.<br>3번째, 4번째도 같은 색이면 계속 발동! 다른 색은 초기화.</p><button id="upgradeClose" class="primary-button">'+(ended?'다음 스테이지 준비 →':'탐험으로 돌아가기 →')+'</button>');$$('[data-upgrade]').forEach(b=>b.onclick=()=>{const i=+b.dataset.upgrade,l=totemLevels[i],cost=upgradeCost(l);if(!totemUnlocked(i)||!cost||magicStars<cost)return;magicStars-=cost;totemLevels[i]++;persist();chord(5);renderTotems();update();openUpgrades(i);});$('#upgradeClose').onclick=()=>{if(ended){if(level<STAGE_COUNT&&stageStars[level-1])level++;reset();}else resume();};}
function openMap(chapter=chapterIndex(level)){if(busy){toast('연쇄가 끝난 뒤 지도를 열 수 있어요.');return;}if(running)pauseClock();showModal('<div class="modal-kicker">100 STAGES · 5 TEMPLES</div><h2>'+chapters[chapter][0]+'</h2><div class="map-tabs">'+chapters.map((c,i)=>'<button data-chapter="'+i+'" class="'+(i===chapter?'active':'')+'">'+String(i*20+1).padStart(2,'0')+'–'+((i+1)*20)+'</button>').join('')+'</div><div class="map-grid">'+Array.from({length:20},(_,n)=>{const stage=chapter*20+n+1,stars=stageStars[stage-1];return '<button data-level="'+stage+'" class="'+(stage===level?'current':stage<unlocked?'done':'')+'" '+(stage>unlocked?'disabled':'')+'>'+String(stage).padStart(2,'0')+'<small>'+(stars?'★'.repeat(stars):stage>unlocked?'잠김':'도전')+'</small></button>';}).join('')+'</div><p class="stars-caption">해금 '+unlocked+' / 100 · 마법별 ★ '+magicStars+'</p><button id="mapUpgrade" class="text-button">토템 강화 <span>↗</span></button><button id="mapClose" class="primary-button">탐험으로 돌아가기 →</button>');$('#mapClose').onclick=resume;$('#mapUpgrade').onclick=()=>openUpgrades();$$('[data-chapter]').forEach(b=>b.onclick=()=>openMap(+b.dataset.chapter));$$('[data-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.level;reset();});}
$('#upgradeBtn').onclick=()=>openUpgrades();
